            const ef = easings[anim.easing] || easings.linear;
            if (isPP) { prog = prog < 0.5 ? ef(prog*2) : ef(2-prog*2); } else { prog = ef(prog); }
            const pose = RigUtils.interpolateKeyframePoses(anim.keyframes, prog);
