            const rc = anim.repeatCount || 1;
            const isInf = anim.repeat === true || rc === Infinity;
            const isCycle = (anim.repeatMode === 'cycle') && (rc > 1 || isInf);
            let lt = animElapsed;
            if (!isInf) lt = Math.min(animElapsed, dur * rc);
            let prog = Math.min((lt % dur) / dur, 1);
            if (!isInf && lt >= dur * rc) prog = 1;
            if (isCycle) { const ci = Math.floor(lt / dur); if (ci % 2 === 1 && !(lt >= dur * rc && !isInf)) prog = 1 - prog; }
